"""TypeScript emitter: vocabulary unions, wire interfaces and document parsers."""
from __future__ import annotations

import json

from schema_model import Model, Type, pascal

HEADER = """// @generated by packages/schemas/codegen/gen.py from packages/schemas/vocabulary.json and
// packages/schemas/json/*.schema.json. Do not edit; run `bash packages/schemas/codegen/gen.sh`.
"""


def doc(text: str, indent: str = "") -> str:
    lines = [l.rstrip() for l in text.strip().splitlines()]
    if not lines:
        return ""
    body = "".join(f"{indent} * {l}\n" if l else f"{indent} *\n" for l in lines)
    return f"{indent}/**\n{body}{indent} */\n"


def ts_type(t: Type) -> str:
    if t.kind == "string":
        base = "string"
    elif t.kind in ("integer", "number"):
        base = "number"
    elif t.kind == "boolean":
        base = "boolean"
    elif t.kind == "any":
        return "unknown"
    elif t.kind == "array":
        inner = ts_type(t.item)
        base = f"({inner})[]" if "|" in inner else f"{inner}[]"
    elif t.kind == "map":
        base = f"Record<string, {ts_type(t.item)}>"
    elif t.kind == "ref":
        base = t.name
    elif t.kind == "enum":
        base = pascal(t.name)
    else:
        raise AssertionError(t.kind)
    return f"{base} | null" if t.nullable else base


def emit_vocabulary(model: Model) -> str:
    out = [HEADER, f'\n/** Version of packages/schemas/vocabulary.json these unions were generated from. */\nexport const VOCABULARY_VERSION = "{model.vocabulary_version}";\n']
    out.append('''
export interface VocabularyValueMetadata {
  /** Canonical Korean screen text. Null means no direct display. */
  readonly screenKo: string | null;
  /** Historical spellings for reference. Wire decoding accepts canonical codes only. */
  readonly deprecatedAliases: readonly string[];
}
''')
    for axis in model.axes.values():
        name = pascal(axis.id)
        has_maps_to = axis.has_maps_to
        has_group = axis.id == "diff_type"
        codes = ", ".join(json.dumps(v["code"]) for v in axis.values)
        out.append("\n" + doc(f"{axis.name_ko}: {axis.concept_ko}\n\nAxis `{axis.id}`."))
        out.append(f"export const {name} = [{codes}] as const;\n")
        out.append(f"export type {name} = (typeof {name})[number];\n")
        metadata_type = "VocabularyValueMetadata"
        if has_maps_to:
            out.append("/** Vocabulary mapping to acquisition status. Archival requires separate evidence. */\n")
            metadata_type += " & { readonly mapsTo: AcquisitionStatus | null }"
        if has_group:
            metadata_type += " & { readonly group: DiffGroup }"
        out.append(f"export const {name}Metadata = {{\n")
        for v in axis.values:
            label = json.dumps(v["screen_ko"], ensure_ascii=False)
            aliases = json.dumps(v["deprecated_aliases"], ensure_ascii=False)
            metadata = f"screenKo: {label}, deprecatedAliases: {aliases}"
            if has_maps_to:
                metadata += f', mapsTo: {json.dumps(v.get("maps_to"))}'
            if has_group:
                metadata += f', group: {json.dumps(v["group"])}'
            out.append(f'  {json.dumps(v["code"])}: {{ {metadata} }},\n')
        out.append(f"}} as const satisfies Readonly<Record<{name}, {metadata_type}>>;\n")
        out.append(
            f"/** Throws on an unknown value: unknown states are never treated as a success. */\n"
            f"export function parse{name}(value: unknown): {name} {{\n"
            f"  if (typeof value === \"string\" && ({name} as readonly string[]).includes(value)) {{\n"
            f"    return value as {name};\n  }}\n"
            f"  throw new Error(`unknown {axis.id}: ${{JSON.stringify(value)}}`);\n}}\n"
        )
    return "".join(out)


def used_axes(model: Model) -> set:
    found = set()

    def walk(t: Type):
        if t.kind == "enum":
            found.add(t.name)
        if t.item is not None:
            walk(t.item)

    for st in model.structs.values():
        for f in st.fields:
            walk(f.type)
    return found


def emit_types(model: Model, structs=None, imports: str | None = None, header: str = HEADER) -> str:
    """`structs`/`imports`/`header` let emit_api reuse this for the API client."""
    if imports is None:
        enums = sorted({pascal(a) for a in used_axes(model)})
        imports = "\nimport type {\n" + "".join(f"  {e},\n" for e in enums) + '} from "./vocabulary";\n'
    out = [header, imports]
    for st in (model.structs.values() if structs is None else structs):
        out.append("\n" + doc(st.description or st.name))
        out.append(f"export interface {st.name} {{\n")
        for f in st.fields:
            if f.description:
                out.append(doc(f.description, "  "))
            q = "" if f.required else "?"
            out.append(f"  {f.name}{q}: {ts_type(f.type)};\n")
        out.append("}\n")
    return "".join(out)


PARSER_HELPERS = '''
type Reader<T> = (value: unknown, path: string) => T;

const objectConstructorSource = Function.prototype.toString.call(Object);

function readObject(value: unknown, path: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${path}: expected an object`);
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    // A foreign realm has its own Object.prototype and native Object constructor.
    const constructor = Object.getOwnPropertyDescriptor(prototype, "constructor")?.value;
    if (
      typeof constructor !== "function" ||
      Function.prototype.toString.call(constructor) !== objectConstructorSource ||
      constructor.prototype !== prototype
    ) {
      throw new TypeError(`${path}: expected a plain object`);
    }
  }
  return value as Record<string, unknown>;
}

function hasField(fields: Record<string, unknown>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(fields, key);
}

function readField<T>(fields: Record<string, unknown>, key: string, path: string, read: Reader<T>): T {
  const fieldPath = `${path}.${key}`;
  if (!hasField(fields, key)) {
    throw new TypeError(`${fieldPath}: missing required field`);
  }
  return read(fields[key], fieldPath);
}

function readString(value: unknown, path: string): string {
  if (typeof value !== "string") throw new TypeError(`${path}: expected a string`);
  return value;
}

function readInteger(value: unknown, path: string): number {
  if (typeof value !== "number" || !Number.isInteger(value)) {
    throw new TypeError(`${path}: expected an integer`);
  }
  return value;
}

function readNumber(value: unknown, path: string): number {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new TypeError(`${path}: expected a finite number`);
  }
  return value;
}

function readBoolean(value: unknown, path: string): boolean {
  if (typeof value !== "boolean") throw new TypeError(`${path}: expected a boolean`);
  return value;
}

const readAny: Reader<unknown> = (value) => value;

function arrayOf<T>(read: Reader<T>): Reader<T[]> {
  return (value, path) => {
    if (!Array.isArray(value)) throw new TypeError(`${path}: expected an array`);
    return Array.from(value, (item, index) => read(item, `${path}[${index}]`));
  };
}

function mapOf<T>(read: Reader<T>): Reader<Record<string, T>> {
  return (value, path) => Object.fromEntries(
    Object.entries(readObject(value, path)).map(([key, item]) => [key, read(item, `${path}[${JSON.stringify(key)}]`)]),
  );
}

function nullable<T>(read: Reader<T>): Reader<T | null> {
  return (value, path) => value === null ? null : read(value, path);
}

function vocabulary<T>(parse: (value: unknown) => T): Reader<T> {
  return (value, path) => {
    try {
      return parse(value);
    } catch {
      throw new TypeError(`${path}: unknown vocabulary value`);
    }
  };
}
'''


def reader(t: Type) -> str:
    if t.kind == "enum":
        expr = f"vocabulary(parse{pascal(t.name)})"
    elif t.kind == "ref":
        expr = f"parse{t.name}"
    elif t.kind == "array":
        expr = f"arrayOf({reader(t.item)})"
    elif t.kind == "map":
        expr = f"mapOf({reader(t.item)})"
    else:
        expr = f"read{pascal(t.kind)}"
    return f"nullable({expr})" if t.nullable and t.kind != "any" else expr


def emit_parsers(model: Model) -> str:
    types = "".join(f"  {name},\n" for name in sorted(model.structs))
    enums = "".join(f"  parse{name},\n" for name in sorted(pascal(a) for a in used_axes(model)))
    out = [HEADER, f'\nimport type {{\n{types}}} from "./types";\n']
    if enums:
        out.append(f'import {{\n{enums}}} from "./vocabulary";\n')
    out.append(PARSER_HELPERS)
    for st in model.structs.values():
        out.append(f'\n/** Decode a JSON value as {st.name}. Throws on invalid field types or enum values. */\n')
        out.append(f'export function parse{st.name}(value: unknown, path = "{st.name}"): {st.name} {{\n')
        if not st.fields:
            out.append("  readObject(value, path);\n  return {};\n}\n")
            continue
        out.append("  const fields = readObject(value, path);\n")
        has_optional = any(not f.required for f in st.fields)
        out.append(f"  const result: {st.name} = {{\n" if has_optional else "  return {\n")
        for f in st.fields:
            if f.required:
                out.append(f'    {f.name}: readField(fields, "{f.name}", path, {reader(f.type)}),\n')
        out.append("  };\n")
        for f in st.fields:
            if not f.required:
                out.append(f'  if (hasField(fields, "{f.name}")) {{\n')
                out.append(f'    result.{f.name} = {reader(f.type)}(fields.{f.name}, `${{path}}.{f.name}`);\n  }}\n')
        if has_optional:
            out.append("  return result;\n")
        out.append("}\n")
    return "".join(out)


def emit_index() -> str:
    return HEADER + 'export * from "./vocabulary";\nexport * from "./types";\nexport * from "./parsers";\n'


def emit_tsconfig() -> str:
    cfg = {
        "compilerOptions": {
            "target": "ES2020", "module": "ES2020", "moduleResolution": "Bundler", "strict": True,
            "noUnusedLocals": True, "noEmit": True, "skipLibCheck": False, "types": [],
        },
        "files": ["index.ts", "vocabulary.ts", "types.ts", "parsers.ts"],
    }
    return json.dumps(cfg, indent=2) + "\n"


def emit_package_json(version: str) -> str:
    pkg = {"name": "onjeon-contracts", "version": version, "private": True,
           "description": "Generated ONJEON contract types and parsers", "types": "index.ts"}
    return json.dumps(pkg, indent=2) + "\n"


def emit(model: Model, version: str) -> dict:
    return {
        "vocabulary.ts": emit_vocabulary(model),
        "types.ts": emit_types(model),
        "parsers.ts": emit_parsers(model),
        "index.ts": emit_index(),
        "tsconfig.json": emit_tsconfig(),
        "package.json": emit_package_json(version),
    }
